import java.util.*;class Solution{public int maximumGap(int[]a){int n=a.length;if(n<2)return 0;int mn=Arrays.stream(a).min().getAsInt(),mx=Arrays.stream(a).max().getAsInt();if(mn==mx)return 0;int sz=(mx-mn+n-2)/(n-1),bc=(mx-mn)/sz+1;int[]lo=new int[bc],hi=new int[bc];boolean[]u=new boolean[bc];Arrays.fill(lo,Integer.MAX_VALUE);Arrays.fill(hi,Integer.MIN_VALUE);for(int x:a){int k=(x-mn)/sz;u[k]=true;lo[k]=Math.min(lo[k],x);hi[k]=Math.max(hi[k],x);}int p=mn,b=0;for(int i=0;i<bc;i++)if(u[i]){b=Math.max(b,lo[i]-p);p=hi[i];}return b;}}
